import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"The Class Codebase","description":"","frontmatter":{"source":"project/class-codebase.md"},"headers":[],"relativePath":"project/class-codebase.md","filePath":"project/class-codebase.md"}'),r={name:"project/class-codebase.md"};function n(i,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="the-class-codebase" tabindex="-1">The Class Codebase <a class="header-anchor" href="#the-class-codebase" aria-label="Permalink to &quot;The Class Codebase&quot;">​</a></h1><blockquote><p>Every team works in the same real open-source project all semester. It&#39;s large enough that nobody can hold it in their head, real enough that its maintainers&#39; standards apply, and, by default, a coding agent itself, so the codebase also teaches the course&#39;s subject.</p></blockquote><h2 id="this-terms-codebase" tabindex="-1">This term&#39;s codebase <a class="header-anchor" href="#this-terms-codebase" aria-label="Permalink to &quot;This term&#39;s codebase&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>This term</th></tr></thead><tbody><tr><td><strong>Project</strong></td><td>[to be confirmed before the term: see TOOLS.md]</td></tr><tr><td><strong>Upstream repository</strong></td><td>[upstream URL]</td></tr><tr><td><strong>License</strong></td><td>[license]</td></tr><tr><td><strong>Language and test command</strong></td><td>[language] · [test command]</td></tr><tr><td><strong>Class fork</strong></td><td><code>[course-org]/[project]</code>, pinned to an upstream release tag, <code>[tag]</code></td></tr><tr><td><strong>Team forks</strong></td><td><code>[course-org]/[project]-team-[n]</code>, forked from the class fork in week 2</td></tr><tr><td><strong>The project&#39;s contribution and AI policies</strong></td><td>[links to its CONTRIBUTING file and AI policy, as read before the term]</td></tr></tbody></table><p>The instructor records the pick, the pinned release and the date it was checked in <a href="./../TOOLS.html">Tool Handout</a> before the term starts.</p><h3 id="build-and-test" tabindex="-1">Build and test <a class="header-anchor" href="#build-and-test" aria-label="Permalink to &quot;Build and test&quot;">​</a></h3><p>Written by the instructor from what actually ran in a fresh Codespace on the default machine, on the pinned release. Follow these steps exactly before improvising.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[install command]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[build command]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[test command]</span></span></code></pre></div><ul><li><strong>Runtime:</strong> [Node or Python version; the course&#39;s standard versions are in TOOLS.md]</li><li><strong>Time to build:</strong> [minutes] · <strong>time to run the tests:</strong> [minutes]</li><li><strong>Tests that already fail on the pinned release:</strong> [none, or the list, so nobody mistakes them for their own breakage]</li><li><strong>Where the agent instructions go:</strong> <code>AGENTS.md</code> at the repository root (<a href="./#where-things-live">what the course adds to it</a>)</li></ul><h2 id="why-a-coding-agents-codebase" tabindex="-1">Why a coding agent&#39;s codebase <a class="header-anchor" href="#why-a-coding-agents-codebase" aria-label="Permalink to &quot;Why a coding agent&#39;s codebase&quot;">​</a></h2><p>Two of the strongest comparable courses converged on the same idea in 2026. Michigan&#39;s EECS 498 dropped its &quot;build the agent&quot; lab and moved its projects into &quot;the real Aider… About 20,000 lines of Python with 12,000 lines of tests&quot;, with the rule &quot;Learn, then design, then build&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a>). CMU&#39;s 17-313 says &quot;we will be building upon opencode, the open source AI coding agent&quot;, and its students fork &quot;a class-specific fork of opencode&quot; (<a href="https://cmu-313.github.io/assignments/P1/" target="_blank" rel="noreferrer">17-313 P1</a>).</p><p>An agent&#39;s codebase does double duty. Onboarding to it teaches you how a real harness manages context, tools, permissions and model providers, which is what weeks 1–4 are about. Changing it is the &quot;large existing codebase&quot; work of weeks 5–13. And your team&#39;s contribution is something you&#39;ll use: a feature, a fix or a test suite for a tool in your own workflow.</p><h2 id="the-default-candidates" tabindex="-1">The default candidates <a class="header-anchor" href="#the-default-candidates" aria-label="Permalink to &quot;The default candidates&quot;">​</a></h2><p>Re-check both before every term; the instructor keeps notes on both.</p><table tabindex="0"><thead><tr><th></th><th><strong>Aider</strong></th><th><strong>opencode</strong></th></tr></thead><tbody><tr><td><strong>What it is</strong></td><td>A terminal coding agent that edits files in a git repository</td><td>An open-source AI coding agent with a terminal interface</td></tr><tr><td><strong>Language</strong></td><td>Python</td><td>TypeScript</td></tr><tr><td><strong>License</strong></td><td>Apache-2.0</td><td>MIT</td></tr><tr><td><strong>Size</strong></td><td>About 20,000 lines of Python plus 12,000 of tests, by Michigan&#39;s count</td><td>Large; check before the term</td></tr><tr><td><strong>Used by</strong></td><td>Michigan EECS 498</td><td>CMU 17-313</td></tr><tr><td><strong>Status at the last check</strong></td><td>Maintenance had slowed sharply: the course&#39;s tool survey calls it dormant, which fails the &quot;active&quot; criterion below unless that has changed (<a href="./../research/notes/tools-senior.html">tools notes</a>)</td><td>Very active, with frequent releases (<a href="./../research/notes/tools-senior.html">tools notes</a>)</td></tr></tbody></table><p><strong>How to read this.</strong> On the last check, opencode met the criteria better; Aider remains a candidate because its size, Python and test suite suit the course well, and because activity can resume. The pick is made against the criteria below, not against this table.</p><h2 id="how-the-codebase-is-chosen" tabindex="-1">How the codebase is chosen <a class="header-anchor" href="#how-the-codebase-is-chosen" aria-label="Permalink to &quot;How the codebase is chosen&quot;">​</a></h2><p>The instructor picks one project before the term, against these criteria. Each criterion is checked and recorded in the instructor&#39;s selection notes.</p><ol><li><strong>A permissive license</strong> (MIT, Apache-2.0, BSD), so a fork, a class fork and student changes raise no licensing questions.</li><li><strong>Active.</strong> Recent commits and releases, and maintainers who respond to issues. In a study of a master&#39;s course, how often a project was committed to predicted student success better than its size or age (<a href="https://research.tue.nl/en/publications/what-barriers-do-students-experience-when-trying-to-contribute-to/" target="_blank" rel="noreferrer">Cassee et al.</a>).</li><li><strong>A real test suite and CI</strong> that pass on the pinned commit, so &quot;CI green&quot; means something from week 2.</li><li><strong>Builds in a Codespace</strong> from its own README, on the default machine, in minutes, so nobody&#39;s laptop decides their grade.</li><li><strong>Approachable issues:</strong> enough labeled or easily scoped issues for every team to find a feature area, plus room for each team&#39;s own proposals.</li><li><strong>An AI-contribution policy that permits disclosed AI assistance,</strong> or no policy that forbids it. A project that declines AI-assisted work (as QEMU&#39;s policy does at the time of writing) is unsuitable even for Tier 1, because Tier 3 must stay possible.</li><li><strong>Manageable size:</strong> large enough to need agents and real comprehension, small enough that a team can find its way around in two weeks. Michigan&#39;s 20,000 lines is a good reference point.</li><li><strong>For Tier 3:</strong> no history of capping or closing outside PRs, and a maintainer contact made before the term (<a href="./contribution-rules.html">contribution rules</a>).</li></ol><p>If no candidate meets criteria 1–6, the course uses the strongest candidate as a class fork for Tiers 1 and 2 and drops Tier 3 for the term, rather than send students to a project that doesn&#39;t want their work.</p><h2 id="what-you-do-first-week-2" tabindex="-1">What you do first (week 2) <a class="header-anchor" href="#what-you-do-first-week-2" aria-label="Permalink to &quot;What you do first (week 2)&quot;">​</a></h2><p>Your first contact with the class codebase is comprehension, not change. That&#39;s where brownfield labs work best: CMU 17-316&#39;s activity has students use an agent to understand an unfamiliar game, generate documentation, and explain it to a neighbor (&quot;Is it good? Correct?&quot;) before changing anything (<a href="https://ai-developer-tools.github.io/assets/pdfs/02-brownfield-vibe-coding-activity.pdf" target="_blank" rel="noreferrer">17-316 activity</a>).</p><p>In the <a href="./../weeks/02-inside-agents/">week 2 Lab</a> you:</p><ol><li><strong>Build it</strong> in a Codespace from the class fork, following <a href="#build-and-test">the build steps above</a> and the project&#39;s own README. Note every step the README got wrong or left out (observed).</li><li><strong>Run its tests</strong> and record the command, the time it takes, and any failures on the pinned commit.</li><li><strong>Map its architecture with an agent:</strong> the entry points, how a user request flows to a model call and back, where tools are defined, where permissions are enforced, how providers are configured, how the tests are organized.</li><li><strong>Verify every claim</strong> in the map: tag each one observed (you opened the file or ran the code) or inferred (the agent said so, or you concluded it), and check the inferred claims that matter. Agents summarize code they haven&#39;t fully read; this is where you learn how often.</li></ol><p>The week 2 assignment turns this into an individual <strong>onboarding report</strong>, which becomes the basis for your team&#39;s M0 proposal. Then:</p><ul><li><strong>Week 2:</strong> teams are announced; each team forks the class fork into the course organization and writes <code>course/TEAM_CHARTER.md</code>.</li><li><strong>Week 3:</strong> you write an <code>AGENTS.md</code> for the class codebase and test whether an agent follows it.</li><li><strong>Week 4:</strong> your team writes <code>course/THREAT_MODEL.md</code> for its own agent setup, before anyone gives an agent broad access to the fork.</li><li><strong>Week 5:</strong> M0, your team&#39;s proposal.</li></ul><h2 id="how-the-class-fork-is-managed" tabindex="-1">How the class fork is managed <a class="header-anchor" href="#how-the-class-fork-is-managed" aria-label="Permalink to &quot;How the class fork is managed&quot;">​</a></h2><ul><li><strong>Pinned.</strong> The class fork starts at one upstream commit, so every team builds on the same base and the course&#39;s labs and answer keys stay valid.</li><li><strong>Syncs are announced.</strong> Staff may merge newer upstream work into the class fork once or twice a term, with a week&#39;s notice and a known-good commit. Teams then merge from the class fork when they&#39;re ready. <strong>Never pull from upstream yourselves</strong>: an unannounced upstream change can break every team&#39;s CI at once.</li><li><strong>If upstream changes its license or AI policy</strong> during the term, the instructor tells the class what changes for Tier 3. Tiers 1 and 2 continue on the class fork.</li><li><strong>Team forks are public</strong>, in the course&#39;s GitHub organization, so free CI and code scanning work and the PR round can happen. They contain only public open-source code and course documents, never grades or personal writing.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Nothing goes upstream except through Tier 3</strong> and its rules (<a href="./contribution-rules.html">contribution rules</a>). CMU&#39;s course says the same: &quot;You should not submit your changes to the parent opencode repository&quot; (<a href="https://cmu-313.github.io/assignments/P2/2_firstsprint/" target="_blank" rel="noreferrer">17-313 P2B</a>).</li><li><strong>Follow the project&#39;s code of conduct and license</strong> in your team fork as you would upstream. Keep the license file and copyright headers as they are.</li><li><strong>Credit what you use.</strong> Code copied from elsewhere needs a compatible license and a note in the PR.</li></ul>`,30)])])}const p=t(r,[["render",n]]);export{g as __pageData,p as default};
